/*
 * Pro tips
 * - Use head only to reach the target; do not search for its predecessor.
 * - Copy the successor value into the target, then bypass that successor.
 * - This changes the visible value sequence without removing the target object itself.
 * - The target cannot be the tail: there is no successor to copy.
 * - Locating the target costs O(position); deletion itself is O(1) time/space. Recursive I/O helpers use O(n) stack space.
 */

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;
import java.util.function.Function;

class Solution {
    public static class Node<T> {
        public T val;
        public Node<T> next;

        public Node(T val) {
            this(val, null);
        }

        public Node(T val, Node<T> next) {
            this.val = val;
            this.next = next;
        }
    }

    public static Node<Integer> deleteNodeWithoutHead(Node<Integer> head, int position) {
        // Navigate to the node at position
        Node<Integer> current = head;
        for (int i = 0; i < position - 1; i++) {
            if (current == null) {
                return head;
            }
            current = current.next;
        }

        // Now current is the node to delete
        if (current == null || current.next == null) {
            return head;  // Can't delete if node is null or last node
        }

        // Copy next node's value to current
        current.val = current.next.val;
        // Skip the next node
        current.next = current.next.next;

        return head;
    }

    public static <T> Node<T> buildList(Iterator<String> iter, Function<String, T> f) {
        if (!iter.hasNext()) return null;
        String val = iter.next();
        Node<T> next = buildList(iter, f);
        return new Node<T>(f.apply(val), next);
    }

    public static List<String> splitWords(String s) {
        return s.isEmpty() ? List.of() : Arrays.asList(s.split(" "));
    }

    public static <T> void formatList(Node<T> node, List<String> out) {
        if (node == null) return;
        out.add(node.val.toString());
        formatList(node.next, out);
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        Node<Integer> head = buildList(splitWords(scanner.nextLine()).iterator(), Integer::parseInt);
        int position = Integer.parseInt(scanner.nextLine());
        scanner.close();
        Node<Integer> res = deleteNodeWithoutHead(head, position);
        ArrayList<String> resArr = new ArrayList<>();
        formatList(res, resArr);
        System.out.println(String.join(" ", resArr));
    }
}
